"""1642 (#117): Test-CarryBody-v1641.ps1 with -PossessCorpse: after the takedown and the presence series, the source
possesses the guard's corpse (Possession with possession_parasite and possession_decayed_harbor granted), walks it
forward 2 s and leaves. Possession of a body is a host-world outcome when Corvo casts it; Emily's copy of the corpse
follows the host's NPC stream (hypothesis). Every 300 ms the case records the corpse's position in both worlds and the
source's position and player states, from the cast until 3 s after the exit. Generated by make_carry_body_v1642.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Test-CarryBody-v1641.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
lines = s.split('\n')
lines.insert(2, "# 1642 (#117): -PossessCorpse possesses the guard's corpse after the takedown and walks it. Generated by make_carry_body_v1642.py.")
s = '\n'.join(lines)
rep("[string]$GrantNamed='')", "[string]$GrantNamed='',[switch]$PossessCorpse)")
block = (
    "   if($PossessCorpse){\n"
    "    foreach($pcItem in 'models/powers/possession/possession.inventoryitem','components/characters/player/base/attributes/possession_parasite.inventoryitem','components/characters/player/base/attributes/possession_decayed_harbor.inventoryitem'){C $source \"coop_grant_named $pcItem\";Start-Sleep -Milliseconds 900}\n"
    "    $pcBody=@($(try{(Q $source '--world-npcs').npcs}catch{@()})|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'});$pcMe=try{(Q $source '--player-states').position}catch{$null}\n"
    "    if(!$pcBody.Count-or!$pcMe){throw 'Possess corpse: no corpse or no source position'}\n"
    "    $pcDx=[double]$pcBody[0].position[0]-$pcMe[0];$pcDy=[double]$pcBody[0].position[1]-$pcMe[1];$pcD=[Math]::Max(.3,[Math]::Sqrt($pcDx*$pcDx+$pcDy*$pcDy))\n"
    "    C $source ('setviewpos {0} {1} {2} {3} 0' -f (F $pcMe[0]),(F $pcMe[1]),(F ([double]$pcMe[2]+1.7)),([Math]::Atan2($pcDy,$pcDx)*180/[Math]::PI).ToString('F4',$inv));Start-Sleep -Milliseconds 400\n"
    "    try{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch ([Math]::Min(60,[Math]::Atan2(1.6,$pcD)*180/[Math]::PI)) -Quick|Out-Null}catch{}\n"
    "    $pcSeries=[Collections.Generic.List[object]]::new();$pcW=[Diagnostics.Stopwatch]::StartNew();$pcStep=0\n"
    "    while($pcW.ElapsedMilliseconds-lt12000){$pcT=$pcW.ElapsedMilliseconds\n"
    "     if($pcStep-eq0){& \"$lab/Send-D2Input.ps1\" -Role $source -LeftTrigger 255 -DurationMs 900|Out-Null;$pcStep=1}\n"
    "     elseif($pcStep-eq1-and$pcT-ge3500){$pcWalk=Start-Process (Get-Process -Id $PID).Path -ArgumentList @('-NoProfile','-File',\"$lab/Send-D2Input.ps1\",'-Role',$source,'-LeftY','14000','-DurationMs','2000') -WindowStyle Hidden -PassThru;$pcStep=2}\n"
    "     elseif($pcStep-eq2-and$pcT-ge7000){& \"$lab/Send-D2Input.ps1\" -Role $source -LeftTrigger 255 -DurationMs 150|Out-Null;$pcStep=3}\n"
    "     $pcRow=[ordered]@{ms=$pcT;step=$pcStep;active=$(try{@((Q $source '--player-states').active|ForEach-Object {$_.id})}catch{$null});me=$(try{(Q $source '--player-states').position}catch{$null})}\n"
    "     foreach($pcR in 'host','client'){$pcN=@($(try{(Q $pcR '--world-npcs').npcs}catch{@()})|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'});$pcRow[$pcR]=$(if($pcN.Count){$pcN[0].position}else{$null})}\n"
    "     $pcSeries.Add([pscustomobject]$pcRow);Start-Sleep -Milliseconds 300}\n"
    "    Save \"$out/$key-possess-corpse.json\" @($pcSeries)\n"
    "    $pcMove={param($pcK)$pcIn=@($pcSeries|Where-Object {$_.$pcK});if($pcIn.Count-lt2){return $null};$pcA=$pcIn[0].$pcK;$pcB=$pcIn[$pcIn.Count-1].$pcK\n"
    "     [Math]::Round([Math]::Sqrt(([double]$pcB[0]-$pcA[0])*([double]$pcB[0]-$pcA[0])+([double]$pcB[1]-$pcA[1])*([double]$pcB[1]-$pcA[1])),2)}\n"
    "    $pcLast=$pcSeries[$pcSeries.Count-1];$pcGap=if($pcLast.host-and$pcLast.client){[Math]::Round([Math]::Sqrt(([double]$pcLast.host[0]-$pcLast.client[0])*([double]$pcLast.host[0]-$pcLast.client[0])+([double]$pcLast.host[1]-$pcLast.client[1])*([double]$pcLast.host[1]-$pcLast.client[1])),2)}else{$null}\n"
    "    $row.possessCorpse=[ordered]@{hostMoved=(& $pcMove 'host');clientMoved=(& $pcMove 'client');sourceMoved=(& $pcMove 'me');endGap=$pcGap;states=@($pcSeries|ForEach-Object {$_.active}|Where-Object {$null-ne$_}|ForEach-Object {[int]$_}|Sort-Object -Unique)}\n"
    "    $row.checks.Add(\"Possessed corpse: moved host $($row.possessCorpse.hostMoved) m, client $($row.possessCorpse.clientMoved) m, end gap $pcGap m; source moved $($row.possessCorpse.sourceMoved) m; states $($row.possessCorpse.states-join ',')\")}\n")
rep("   $row.passed=$true;throw 'presence-done'\n", block + "   $row.passed=$true;throw 'presence-done'\n")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Test-CarryBody-v1642.ps1').write_bytes(out.encode('utf-8'))
print('ok')
